SELECT  FROM chat_run
WHERE user_id = #{userId} AND session_id = #{sessionId}
  AND status IN ('created', 'running', 'waiting_compaction', 'waiting_tool', 'steer_requested',
                 'cancel_requested', 'cancelling') AND deleted = 0
AND (tenant_id IS NULL OR tenant_id = '')AND tenant_id = #{tenantId}
ORDER BY id ASC

SELECT  FROM chat_run
WHERE source_type = #{sourceType} AND source_id = #{sourceId}
  AND status IN ('created', 'running', 'waiting_compaction', 'waiting_tool', 'steer_requested',
                 'cancel_requested', 'cancelling') AND deleted = 0
AND (tenant_id IS NULL OR tenant_id = '')AND tenant_id = #{tenantId}
ORDER BY id ASC

