UPDATE chat_run SET user_message_id = #{messageId}, version = version + 1
WHERE user_id = #{userId} AND run_id = #{runId} AND version = #{expectedVersion} AND deleted = 0
AND (tenant_id IS NULL OR tenant_id = '')AND tenant_id = #{tenantId}

UPDATE chat_run SET successor_run_id = #{successorRunId}, steer_instruction = #{steerInstruction}, version = version + 1
WHERE user_id = #{userId} AND run_id = #{runId} AND version = #{expectedVersion} AND deleted = 0
AND (tenant_id IS NULL OR tenant_id = '')AND tenant_id = #{tenantId}

UPDATE chat_run SET current_context_revision = #{contextRevision}, version = version + 1
WHERE user_id = #{userId} AND run_id = #{runId} AND version = #{expectedVersion} AND deleted = 0
AND (tenant_id IS NULL OR tenant_id = '')AND tenant_id = #{tenantId}
